interface.definition:
a!localVariables(
  {
    #"_a-0000ef9e-7f0c-8000-9e5a-011c48011c48_1323830"(show: ri!show),
    /* ===== BASIC DETAILS SECTION ===== */
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "",
      labelSize: "MEDIUM",
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          labelPosition: "COLLAPSED",
          value: {
            #"SYSTEM_SYSRULES_richTextIcon"(
              icon: "info-circle",
              color: "ACCENT"
            ),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: " Basic Details",
              size: "MEDIUM",
              style: "STRONG"
            )
          },
          marginBelow: "STANDARD"
        ),
        #"SYSTEM_SYSRULES_cardLayout"(
          contents: {
            #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Application Name",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/934fe72d-d285-4f56-bb33-55edd415c5de"],
                        "–"
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Application ID",
                      labelPosition: "JUSTIFIED",
                      value: if(
                        a!isNullOrEmpty(
                          ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/3e4edb1b-316e-460a-81f3-b7e7315ce7c2"]
                        ),
                        "–",
                        "APP-" & text(
                          ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/3e4edb1b-316e-460a-81f3-b7e7315ce7c2"],
                          "00000"
                        )
                      )
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Application Description",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/fe3c2d5d-d09f-48a6-9692-dd3ee4f80925"],
                        "–"
                      )
                    )
                  }
                )
              }
            )
          },
          style: "NONE",
          padding: "STANDARD",
          marginBelow: "STANDARD",
          showBorder: false,
          showShadow: true
        )
      }
    ),

    /* ===== SYSTEM DETAILS SECTION ===== */
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "",
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          labelPosition: "COLLAPSED",
          value: {
            #"SYSTEM_SYSRULES_richTextIcon"(
              icon: "cog",
