                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Modified On",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        #"_a-0000eef8-4604-8000-9e54-011c48011c48_1122127"(
                          ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/2ae72cda-12f5-48a2-bf61-706f697f6734"]
